import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { mkFixture, runCli, sampleFeatureJson } from './helpers.mjs';
import { buildBrief } from '../plugin/scripts/lib/brief.mjs';
import { parsePlan, findTask } from '../plugin/scripts/lib/plan.mjs';
import { sliceMap } from '../plugin/scripts/lib/map.mjs';

const SHA = 'a'.repeat(40);
const MAP_TEXT = `# Codebase map
<!-- dev-cycle map v1 head=${SHA}; generated by \`dev-cycle map\`, edit only ## Notes -->

## Root
- package manager: pnpm
- dirs: apps/, packages/

## Package apps/web
- name: web
- scripts: build, test

## Package packages/ui
- name: ui

## Notes

<!-- Maintained by discovery. -->
- \`apps/web/**\` — server actions live in app/actions
`;

const fixtureText = (n) => fs.readFileSync(new URL(`./fixtures/brief/${n}`, import.meta.url), 'utf8');
const PLAN = fixtureText('plan.md');
const SPEC = fixtureText('spec.md');
const task3 = () => findTask(parsePlan(PLAN), 3);
const fj = () => sampleFeatureJson({ profile: { guards: ['G'], rules: [] } });

test('AC18: brief 3 puts ## Project map right after Project rules', () => {
  const fx = mkFixture({ featureJson: fj(), files: { 'plan.md': PLAN, 'spec.md': SPEC } });
  try {
    fx.write('.dev-cycle/map.md', MAP_TEXT);
    const r = runCli(['brief', '3'], { cwd: fx.root });
    assert.equal(r.status, 0, r.stderr);
    const md = fs.readFileSync(path.join(fx.featureDir, 'briefs', 'task-3.md'), 'utf8');
    const heads = [...md.matchAll(/^## (.+)$/gm)].map((m) => m[1]);
    const i = heads.indexOf('Project rules');
    assert.equal(heads[i + 1], 'Project map');
    const slice = sliceMap(MAP_TEXT, task3().touches);
    assert.ok(slice !== '' && md.includes(`## Project map\n\n${slice.replace(/\n+$/, '')}\n\n`));
  } finally { fx.cleanup(); }
});

test('AC18: no map means no section; map null equals omitted', () => {
  const fx = mkFixture({ featureJson: fj(), files: { 'plan.md': PLAN, 'spec.md': SPEC } });
  try {
    const r = runCli(['brief', '3'], { cwd: fx.root });
    assert.equal(r.status, 0, r.stderr);
    assert.ok(!fs.readFileSync(path.join(fx.featureDir, 'briefs', 'task-3.md'), 'utf8').includes('## Project map'));
  } finally { fx.cleanup(); }
  const base = { task: task3(), specText: SPEC, fj: fj() };
  assert.equal(buildBrief({ ...base, map: null }), buildBrief(base));
});
